const FLEET_SIZES = new Set(['1-5', '6-10', '11-25', '26-50', '51-100', '100+']);
const LANGUAGES = new Set(['en', 'es']);
const EXPECTED_SOURCE = 'ekilibrium-technologies-website';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const ENVELOPE_KEYS = new Set(['headers', 'params', 'query', 'body', 'webhookUrl', 'executionMode']);
const ALLOWED_LEAD_KEYS = new Set([
  'firstName',
  'lastName',
  'company',
  'email',
  'phone',
  'fleetSize',
  'currentSoftware',
  'challenge',
  'language',
  'source',
  'submittedAt',
]);

const reject = (status, error) => [{
  json: {
    valid: false,
    status,
    error,
  },
}];

const root = items[0]?.json ?? {};
const leadSource =
  root.body && typeof root.body === 'object' && !Array.isArray(root.body)
    ? root.body
    : Object.fromEntries(
        Object.entries(root).filter(([key]) => !ENVELOPE_KEYS.has(key)),
      );

if (!leadSource || typeof leadSource !== 'object' || Array.isArray(leadSource)) {
  return reject(400, 'invalid_request');
}

for (const key of Object.keys(leadSource)) {
  if (!ALLOWED_LEAD_KEYS.has(key)) {
    return reject(400, 'invalid_request');
  }
}

const asTrimmedString = (value) =>
  typeof value === 'string' ? value.trim() : null;

const requiredString = (key, max) => {
  const value = asTrimmedString(leadSource[key]);
  if (!value || value.length > max) {
    return null;
  }
  return value;
};

const optionalString = (key, max) => {
  if (!(key in leadSource) || leadSource[key] === null || leadSource[key] === undefined) {
    return '';
  }
  const value = asTrimmedString(leadSource[key]);
  if (value === null || value.length > max) {
    return null;
  }
  return value;
};

const firstName = requiredString('firstName', 80);
const lastName = requiredString('lastName', 80);
const company = requiredString('company', 120);
const emailRaw = requiredString('email', 254);
const fleetSize = requiredString('fleetSize', 20);
const challenge = requiredString('challenge', 2000);
const language = requiredString('language', 8);
const source = requiredString('source', 80);
const submittedAt = requiredString('submittedAt', 64);
const phone = optionalString('phone', 40);
const currentSoftware = optionalString('currentSoftware', 120);

if (
  !firstName ||
  !lastName ||
  !company ||
  !emailRaw ||
  !fleetSize ||
  !challenge ||
  !language ||
  !source ||
  !submittedAt ||
  phone === null ||
  currentSoftware === null
) {
  return reject(400, 'invalid_request');
}

const email = emailRaw.toLowerCase();
if (!EMAIL_RE.test(email)) {
  return reject(400, 'invalid_request');
}

if (!FLEET_SIZES.has(fleetSize) || !LANGUAGES.has(language)) {
  return reject(400, 'invalid_request');
}

if (source !== EXPECTED_SOURCE) {
  return reject(400, 'invalid_request');
}

if (Number.isNaN(Date.parse(submittedAt))) {
  return reject(400, 'invalid_request');
}

const receivedAt = new Date().toISOString();
const lead = {
  firstName,
  lastName,
  fullName: (firstName + ' ' + lastName).trim(),
  company,
  email,
  phone,
  fleetSize,
  currentSoftware,
  challenge,
  language,
  source,
  submittedAt,
  receivedAt,
};

return [
  {
    json: {
      valid: true,
      status: 200,
      lead,
      summary: {
        language: lead.language,
        fleetSize: lead.fleetSize,
        source: lead.source,
        submittedAt: lead.submittedAt,
        receivedAt: lead.receivedAt,
        hasPhone: Boolean(lead.phone),
        hasCurrentSoftware: Boolean(lead.currentSoftware),
      },
    },
  },
];
